        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_tether_core_fn_free_sessionrunner(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_tether_core_fn_clone_sessionrunner(handle, status)
        }
    }

    
    /**
     * Clears future model context while preserving the transcript.
     *
     * # Errors
     * Returns an error when the actor is stopped or storage is unavailable.
     */
    @Throws(SessionRuntimeException::class)override fun `clearContext`()
        = 
    callWithHandle {
    uniffiRustCallWithError(SessionRuntimeException) { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_clear_context(
        it,
        _status)
}
    }
    
    

    
    /**
     * Cancels the active turn. Saved text remains in the transcript.
     */override fun `interrupt`()
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_interrupt(
        it,
        _status)
}
    }
    
    

    
    /**
     * Stops a running turn and restores a saved checkpoint in actor order.
     * Call from a background thread.
     *
     * # Errors
     * Returns an error when the checkpoint is absent or restoration fails.
     */
    @Throws(SessionRuntimeException::class)override fun `rewind`(`checkpointId`: kotlin.String, `scope`: RewindScopeView)
        = 
    callWithHandle {
    uniffiRustCallWithError(SessionRuntimeException) { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_rewind(
        it,
        
        FfiConverterString.lower(`checkpointId`),
        FfiConverterTypeRewindScopeView.lower(`scope`),_status)
}
    }
    
    

    
    /**
     * Queues a plain text turn. Events arrive through the runtime's sink.
     * Call from a background thread.
     *
     * # Errors
     * Returns an error for empty input or a stopped actor.
     */
    @Throws(SessionRuntimeException::class)override fun `sendMessage`(`text`: kotlin.String)
        = 
    callWithHandle {
    uniffiRustCallWithError(SessionRuntimeException) { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_send_message(
        it,
        
        FfiConverterString.lower(`text`),_status)
}
    }
    
    

    
    /**
     * Queues a turn and returns resolved and skipped file mentions.
     *
     * # Errors
     * Returns an error for empty input, a stopped actor, or unavailable storage.
     */
    @Throws(SessionRuntimeException::class)override fun `sendMessageWithOutcome`(`text`: kotlin.String): SendOutcomeView {
            return FfiConverterTypeSendOutcomeView.lift(
    callWithHandle {
    uniffiRustCallWithError(SessionRuntimeException) { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_send_message_with_outcome(
        it,
        
        FfiConverterString.lower(`text`),_status)
}
    }
    )
    }
    

    
    /**
     * Reads the session's background process table without waiting for a turn.
     *
     * A plain chat session has no process manager and returns an empty list.

     */override fun `listProcesses`(): List<ProcessView> {
            return FfiConverterSequenceTypeProcessView.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_list_processes(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Stops one session-owned background process without waiting for a turn.
     *
     * Stopping a process that has already stopped is successful. Plain chat
     * sessions and sessions without Linux tools report `NotFound`.
     *
     * # Errors
     * Returns `NotFound` for an unknown process or a session without a process
     * manager, and `Unavailable` when the process table cannot be read.
     */
    @Throws(SessionRuntimeException::class)override fun `stopProcess`(`processId`: kotlin.String)
        = 
    callWithHandle {
    uniffiRustCallWithError(SessionRuntimeException) { _status ->
    UniffiLib.uniffi_tether_core_fn_method_sessionrunner_stop_process(
        it,
        
        FfiConverterString.lower(`processId`),_status)
}
    }
    
    

    
    /**
     * Stops a running turn and hides the given message and every later one.
     * Files are not restored. Call from a background thread.
