    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeBudgetScopeView: FfiConverterRustBuffer<BudgetScopeView> {
    override fun read(buf: ByteBuffer) = try {
        BudgetScopeView.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: BudgetScopeView) = 4UL

    override fun write(value: BudgetScopeView, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Errors from CI runtime calls.
 */
sealed class CiRuntimeException: kotlin.Exception() {
    
    /**
     * The project or repository is absent.
     */
    class Repository(
        ) : CiRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * GitHub sign-in is absent.
     */
    class NotSignedIn(
        ) : CiRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * The project has no GitHub remote.
     */
    class NoRemote(
        ) : CiRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * Storage or runtime setup failed.
     */
    class Unavailable(
        ) : CiRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * GitHub returned an error.
     */
    class Github(
        
        /**
         * Safe error detail.
         */
        val `detail`: kotlin.String
        ) : CiRuntimeException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CiRuntimeException> {
        override fun lift(error_buf: RustBuffer.ByValue): CiRuntimeException = FfiConverterTypeCiRuntimeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCiRuntimeError : FfiConverterRustBuffer<CiRuntimeException> {
    override fun read(buf: ByteBuffer): CiRuntimeException {
        

        return when(buf.getInt()) {
            1 -> CiRuntimeException.Repository()
            2 -> CiRuntimeException.NotSignedIn()
            3 -> CiRuntimeException.NoRemote()
            4 -> CiRuntimeException.Unavailable()
            5 -> CiRuntimeException.Github(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CiRuntimeException): ULong {
        return when(value) {
            is CiRuntimeException.Repository -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CiRuntimeException.NotSignedIn -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CiRuntimeException.NoRemote -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CiRuntimeException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CiRuntimeException.Github -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CiRuntimeException, buf: ByteBuffer) {
        when(value) {
            is CiRuntimeException.Repository -> {
                buf.putInt(1)
                Unit
            }
            is CiRuntimeException.NotSignedIn -> {
                buf.putInt(2)
                Unit
            }
            is CiRuntimeException.NoRemote -> {
                buf.putInt(3)
                Unit
            }
            is CiRuntimeException.Unavailable -> {
                buf.putInt(4)
                Unit
            }
            is CiRuntimeException.Github -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * A command could not be resolved.
 */
sealed class CommandRuntimeException: kotlin.Exception() {
    
    /**
     * No command matched the input.
     */
    class Unknown(
        
        /**
         * Typed command name.
         */
        val `name`: kotlin.String, 
        
        /**
         * Closest command names.
         */
        val `suggestions`: List<kotlin.String>
        ) : CommandRuntimeException() {
        override val message
            get() = "name=${ `name` }, suggestions=${ `suggestions` }"
    }
    
    /**
     * A command requires a disabled capability.
     */
    class Unavailable(
        
        /**
         * Plain explanation. Not named `message`: a UniFFI error field of that name clashes
         * with the Kotlin exception's own `message`.
         */
        val `reason`: kotlin.String
        ) : CommandRuntimeException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CommandRuntimeException> {
        override fun lift(error_buf: RustBuffer.ByValue): CommandRuntimeException = FfiConverterTypeCommandRuntimeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCommandRuntimeError : FfiConverterRustBuffer<CommandRuntimeException> {
    override fun read(buf: ByteBuffer): CommandRuntimeException {
        

        return when(buf.getInt()) {
            1 -> CommandRuntimeException.Unknown(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            2 -> CommandRuntimeException.Unavailable(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CommandRuntimeException): ULong {
        return when(value) {
            is CommandRuntimeException.Unknown -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterSequenceString.allocationSize(value.`suggestions`)
            )
            is CommandRuntimeException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CommandRuntimeException, buf: ByteBuffer) {
        when(value) {
            is CommandRuntimeException.Unknown -> {
                buf.putInt(1)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterSequenceString.write(value.`suggestions`, buf)
                Unit
            }
            is CommandRuntimeException.Unavailable -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



