/**
 * What kind of failure a [`CoreErrorView`] reports.
 */

enum class ErrorKindView {
    
    /**
     * A bug in Tether.
     */
    INTERNAL,
    /**
     * The network failed or timed out.
     */
    NETWORK,
    /**
     * A provider or GitHub rejected the credentials.
     */
    AUTH,
    /**
     * A provider asked the client to slow down.
     */
    RATE_LIMITED,
    /**
     * The request itself was wrong.
     */
    INVALID_INPUT,
    /**
     * The thing asked for does not exist.
     */
    NOT_FOUND,
    /**
     * The user or the system cancelled the work.
     */
    CANCELLED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeErrorKindView: FfiConverterRustBuffer<ErrorKindView> {
    override fun read(buf: ByteBuffer) = try {
        ErrorKindView.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ErrorKindView) = 4UL

    override fun write(value: ErrorKindView, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Errors from executor configuration and project network settings.
 */
sealed class ExecutorRuntimeException: kotlin.Exception() {
    
    /**
     * A path or key setting was invalid.
     */
    class InvalidConfiguration(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * The database or local configuration could not be read or written.
     */
    class Unavailable(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * The download did not pass its signature or content check.
     */
    class VerificationFailed(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * A setup or install did not finish. `reason` is a short, safe description.
     */
    class SetupFailed(
        
        /**
         * What failed, in a sentence. It can include the end of the package installer's output,
         * which names package repositories but never a token or file contents.
         */
        val `reason`: kotlin.String
        ) : ExecutorRuntimeException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The requested project does not exist.
     */
    class ProjectNotFound(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * Linux mode is not installed or cannot be used yet.
     */
    class LinuxNotReady(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    
    /**
     * One interactive Linux shell is already open for this executor runtime.
     */
    class LinuxShellAlreadyOpen(
        ) : ExecutorRuntimeException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ExecutorRuntimeException> {
        override fun lift(error_buf: RustBuffer.ByValue): ExecutorRuntimeException = FfiConverterTypeExecutorRuntimeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeExecutorRuntimeError : FfiConverterRustBuffer<ExecutorRuntimeException> {
    override fun read(buf: ByteBuffer): ExecutorRuntimeException {
        

        return when(buf.getInt()) {
            1 -> ExecutorRuntimeException.InvalidConfiguration()
            2 -> ExecutorRuntimeException.Unavailable()
            3 -> ExecutorRuntimeException.VerificationFailed()
            4 -> ExecutorRuntimeException.SetupFailed(
                FfiConverterString.read(buf),
                )
            5 -> ExecutorRuntimeException.ProjectNotFound()
            6 -> ExecutorRuntimeException.LinuxNotReady()
            7 -> ExecutorRuntimeException.LinuxShellAlreadyOpen()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ExecutorRuntimeException): ULong {
        return when(value) {
            is ExecutorRuntimeException.InvalidConfiguration -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ExecutorRuntimeException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ExecutorRuntimeException.VerificationFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ExecutorRuntimeException.SetupFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is ExecutorRuntimeException.ProjectNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ExecutorRuntimeException.LinuxNotReady -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ExecutorRuntimeException.LinuxShellAlreadyOpen -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ExecutorRuntimeException, buf: ByteBuffer) {
        when(value) {
            is ExecutorRuntimeException.InvalidConfiguration -> {
                buf.putInt(1)
                Unit
            }
            is ExecutorRuntimeException.Unavailable -> {
                buf.putInt(2)
                Unit
            }
            is ExecutorRuntimeException.VerificationFailed -> {
                buf.putInt(3)
                Unit
            }
            is ExecutorRuntimeException.SetupFailed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is ExecutorRuntimeException.ProjectNotFound -> {
                buf.putInt(5)
                Unit
            }
            is ExecutorRuntimeException.LinuxNotReady -> {
                buf.putInt(6)
                Unit
            }
            is ExecutorRuntimeException.LinuxShellAlreadyOpen -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



